def transform(grid):
    # The grid is an arithmetic/cyclic pattern: rows advance the start value,
    # columns advance cyclically. Diagonal cells are doubled in the source;
    # zeroed patches are occlusions. Recover the value by modular progression.
    h, w = len(grid), len(grid[0])
    # Main pattern is 2,3,...,9,1 cyclically across columns and fixed per row
    # as 3 for rows below the first; diagonal marks are replaced by the row's
    # diagonal value, which is column+1 modulo 9 (colors 1..9).
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            if r == 0 and c == 0:
                v = 2
            elif c == 0:
                v = 3
            else:
                v = ((c + 1) % 9) + 1
            # diagonal staircase uses the repeated value at r=c (within first 23)
            if r == c:
                v = grid[r][c] if grid[r][c] != 0 else ((c + 1) % 9) + 1
            row.append(v)
        out.append(row)
    return out
